export function createFormatter(options) {
  const strategies = { plain: (value) => String(value) };
  const pick = strategies[options.kind] ?? strategies.plain;
  return { format: (value) => pick(value) };
}

into.ts:
export function createFormatter(options: { kind: string }): { format: (value: unknown) => string } {
  const strategies: Record<string, (value: unknown) => string> = { plain: (value) => String(value) };
  const pick = strategies[options.kind] ?? strategies.plain;
  return { format: (value) => pick(value) };
}
